package org.synqoria.scheduling;
import java.time.*;import java.util.*;import java.sql.*;import java.lang.reflect.*;
/** Ten individual executable recovery-branch batch tests; deterministic fixtures only. */
public final class V030SchedulingRecoveryTest {
 static int checks=0;
 static void ok(boolean b){checks++;if(!b)throw new AssertionError("Check "+checks);}
 static void denied(Runnable r){boolean rejected=false;try{r.run();}catch(RuntimeException x){rejected=true;}ok(rejected);}
 static final UUID CELL=UUID.fromString("00000000-0000-0000-0000-000000000001"), TENANT=UUID.fromString("00000000-0000-0000-0000-000000000002"), FACILITY=UUID.fromString("00000000-0000-0000-0000-000000000003"),RESOURCE=UUID.fromString("00000000-0000-0000-0000-000000000004");
 static SchedulingScope scope(){return new SchedulingScope(CELL,TENANT,FACILITY);}
 static AppointmentWindow window(){return new AppointmentWindow(Instant.parse("2026-11-01T09:00:00Z"),Instant.parse("2026-11-01T09:30:00Z"),ZoneId.of("Africa/Douala"));}
 static void b10(){ok(scope().equals(scope()));denied(()->scope().requireSame(new SchedulingScope(CELL,UUID.randomUUID(),FACILITY)));denied(()->new SchedulingScope(null,TENANT,FACILITY));scope().requireSame(scope());ok(!scope().equals(new SchedulingScope(UUID.randomUUID(),TENANT,FACILITY)));}
 static void b11(){var w=AppointmentWindow.fromLocal(LocalDateTime.parse("2026-11-01T10:00:00"),ZoneId.of("Africa/Douala"),null,Duration.ofMinutes(30));ok(w.start().equals(Instant.parse("2026-11-01T09:00:00Z")));ok(w.overlaps(window()));denied(()->AppointmentWindow.fromLocal(LocalDateTime.parse("2026-03-29T02:30:00"),ZoneId.of("Europe/Paris"),null,Duration.ofMinutes(30)));denied(()->AppointmentWindow.fromLocal(LocalDateTime.parse("2026-10-25T02:30:00"),ZoneId.of("Europe/Paris"),null,Duration.ofMinutes(30)));denied(()->new AppointmentWindow(window().start(),window().start(),window().zone()));}
 static void b12(){var r=new ResourceConflictFence.Reservation(scope(),RESOURCE,window(),true);ok(ResourceConflictFence.conflicts(r,List.of(r)));ok(!ResourceConflictFence.conflicts(r,List.of(new ResourceConflictFence.Reservation(scope(),UUID.randomUUID(),window(),true))));ok(!ResourceConflictFence.conflicts(r,List.of(new ResourceConflictFence.Reservation(scope(),RESOURCE,window(),false))));ok(!ResourceConflictFence.conflicts(r,List.of(new ResourceConflictFence.Reservation(scope(),RESOURCE,new AppointmentWindow(window().end(),window().end().plusSeconds(60),window().zone()),true))));denied(()->ResourceConflictFence.conflicts(r,Arrays.asList((ResourceConflictFence.Reservation)null)));}
 static void b13(){var e=new ClinicianEligibilityFence.Evidence(UUID.randomUUID(),scope(),Set.of("CARDIOLOGY"),window().start().minusSeconds(60),window().end().plusSeconds(60),3,true,false);ok(ClinicianEligibilityFence.eligible(e,scope(),"CARDIOLOGY",window(),3));ok(!ClinicianEligibilityFence.eligible(e,scope(),"ORTHOPAEDICS",window(),3));ok(!ClinicianEligibilityFence.eligible(e,scope(),"CARDIOLOGY",window(),4));ok(!ClinicianEligibilityFence.eligible(e,new SchedulingScope(CELL,TENANT,UUID.randomUUID()),"CARDIOLOGY",window(),3));ok(!ClinicianEligibilityFence.eligible(new ClinicianEligibilityFence.Evidence(e.clinicianId(),scope(),e.competencies(),e.shiftStart(),e.shiftEnd(),3,true,true),scope(),"CARDIOLOGY",window(),3));}
 static void b14(){ok(AppointmentLifecycleFence.mayTransition(AppointmentLifecycleFence.State.REQUESTED,AppointmentLifecycleFence.State.CONFIRMED));ok(AppointmentLifecycleFence.mayTransition(AppointmentLifecycleFence.State.CONFIRMED,AppointmentLifecycleFence.State.NO_SHOW));ok(!AppointmentLifecycleFence.mayTransition(AppointmentLifecycleFence.State.FULFILLED,AppointmentLifecycleFence.State.CONFIRMED));ok(!AppointmentLifecycleFence.mayTransition(AppointmentLifecycleFence.State.CONFIRMED,AppointmentLifecycleFence.State.FULFILLED));denied(()->AppointmentLifecycleFence.require(AppointmentLifecycleFence.State.CONFIRMED,AppointmentLifecycleFence.State.CANCELLED," "));AppointmentLifecycleFence.require(AppointmentLifecycleFence.State.CONFIRMED,AppointmentLifecycleFence.State.CANCELLED,"patient request");ok(true);}
 static void b15(){byte[] digest=new byte[32];digest[0]=3;UUID cmd=UUID.randomUUID();var a=new BookingReplayFence.Claim(cmd,scope(),digest);ok(BookingReplayFence.evaluate(a,null)==BookingReplayFence.Outcome.NEW);ok(BookingReplayFence.evaluate(a,new BookingReplayFence.Claim(cmd,scope(),digest))==BookingReplayFence.Outcome.SAFE_REPLAY);digest[0]=5;ok(BookingReplayFence.evaluate(a,new BookingReplayFence.Claim(cmd,scope(),digest))==BookingReplayFence.Outcome.CONFLICT);ok(BookingReplayFence.evaluate(a,new BookingReplayFence.Claim(UUID.randomUUID(),scope(),a.digest()))==BookingReplayFence.Outcome.CONFLICT);denied(()->new BookingReplayFence.Claim(cmd,scope(),new byte[20]));}
 static void b16(){var now=Instant.parse("2026-11-01T09:00:00Z");var h=new BookingHoldFence(UUID.randomUUID(),scope(),now,now.plusSeconds(120));ok(h.current(now,scope()));ok(!h.current(now.plusSeconds(120),scope()));ok(!h.current(now.minusSeconds(1),scope()));ok(!h.current(now,new SchedulingScope(CELL,TENANT,UUID.randomUUID())));denied(()->new BookingHoldFence(UUID.randomUUID(),scope(),now,now.plusSeconds(901)));}
 static void b17(){var r=new ResourceConflictFence.Reservation(scope(),RESOURCE,window(),true);ok(ResourceCapacityFence.hasCapacity(scope(),RESOURCE,window(),2,List.of(r)));ok(!ResourceCapacityFence.hasCapacity(scope(),RESOURCE,window(),1,List.of(r)));ok(ResourceCapacityFence.hasCapacity(scope(),RESOURCE,window(),1,List.of(new ResourceConflictFence.Reservation(new SchedulingScope(CELL,TENANT,UUID.randomUUID()),RESOURCE,window(),true))));ok(ResourceCapacityFence.hasCapacity(scope(),RESOURCE,window(),1,List.of(new ResourceConflictFence.Reservation(scope(),RESOURCE,window(),false))));denied(()->ResourceCapacityFence.hasCapacity(scope(),RESOURCE,window(),0,List.of()));}
 static Object defaultValue(Class<?> type){if(type==boolean.class)return false;if(type==int.class)return 0;if(type==long.class)return 0L;return null;}
 static void b18()throws Exception{
  var captured=new ArrayList<Object>();UUID appt=UUID.randomUUID();
  ResultSet rs=(ResultSet)Proxy.newProxyInstance(V030SchedulingRecoveryTest.class.getClassLoader(),new Class[]{ResultSet.class},(proxy,m,a)->{
   if(m.getName().equals("next")){captured.add("next");return false;} // no rows
   return defaultValue(m.getReturnType());});
  PreparedStatement ps=(PreparedStatement)Proxy.newProxyInstance(V030SchedulingRecoveryTest.class.getClassLoader(),new Class[]{PreparedStatement.class},(proxy,m,a)->{
   if(m.getName().equals("setObject")){captured.add(a[0]+":"+a[1]);return null;}if(m.getName().equals("executeQuery"))return rs;return defaultValue(m.getReturnType());});
  Connection cx=(Connection)Proxy.newProxyInstance(V030SchedulingRecoveryTest.class.getClassLoader(),new Class[]{Connection.class},(proxy,m,a)->{
   return switch(m.getName()){case "isClosed"->false;case "getAutoCommit"->false;case "isReadOnly"->true;case "getTransactionIsolation"->Connection.TRANSACTION_REPEATABLE_READ;case "prepareStatement"->{ok(ScopedAppointmentJdbcRead.SQL.equals(a[0]));yield ps;} default->defaultValue(m.getReturnType());};});
  ok(!ScopedAppointmentJdbcRead.exists(cx,scope(),appt));ok(captured.contains("1:"+CELL));ok(captured.contains("2:"+TENANT));ok(captured.contains("3:"+FACILITY));ok(captured.contains("4:"+appt));
  Connection unsafe=(Connection)Proxy.newProxyInstance(V030SchedulingRecoveryTest.class.getClassLoader(),new Class[]{Connection.class},(proxy,m,a)->{if(m.getName().equals("getAutoCommit"))return true;return defaultValue(m.getReturnType());});
  boolean blocked=false;try{ScopedAppointmentJdbcRead.exists(unsafe,scope(),appt);}catch(SQLException e){blocked=true;}ok(blocked);
 }
 static void b19(){byte[] h=new byte[32];UUID command=UUID.randomUUID(),corr=UUID.randomUUID(),event=UUID.randomUUID();var a=new BookingAuditOutboxFence.Receipt(scope(),command,corr,event,h,true);var o=new BookingAuditOutboxFence.Receipt(scope(),command,corr,event,h,true);ok(BookingAuditOutboxFence.consistent(a,o,true));ok(!BookingAuditOutboxFence.consistent(a,o,false));ok(!BookingAuditOutboxFence.consistent(a,new BookingAuditOutboxFence.Receipt(scope(),command,UUID.randomUUID(),event,h,true),true));ok(!BookingAuditOutboxFence.consistent(a,new BookingAuditOutboxFence.Receipt(scope(),command,corr,event,h,false),true));byte[] changed=h.clone();changed[0]=9;ok(!BookingAuditOutboxFence.consistent(a,new BookingAuditOutboxFence.Receipt(scope(),command,corr,event,changed,true),true));}
 public static void main(String[] args)throws Exception{
  if(args.length!=1)throw new IllegalArgumentException("Specify exactly one batch");
  switch(args[0]){case "P06-B0010"->b10();case "P06-B0011"->b11();case "P06-B0012"->b12();case "P06-B0013"->b13();case "P06-B0014"->b14();case "P06-B0015"->b15();case "P06-B0016"->b16();case "P06-B0017"->b17();case "P06-B0018"->b18();case "P06-B0019"->b19();default->throw new IllegalArgumentException("Unknown batch");}
  System.out.println("PASS "+args[0]+" assertions="+checks);
 }
}
